import{_ as d,c as o,o as e,b0 as a}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/iap-end-to-end.Gi-4i-2X.svg",u=JSON.parse('{"title":"LV060-IAP升级完整流程","description":null,"frontmatter":{"title":"LV060-IAP升级完整流程","date":"2026-10-17T21:10:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/online-upgrade/iap/126b0fd3f48eb7e4c2a91","index":true,"tags":null,"categories":["在线升级"],"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-17T21:10:00.410Z","fulluuid":"b7e4c2a91d3f48e6a0c57b138f2d6e94","useduuid":"b7e4c2a91"}},"headers":[],"relativePath":"sdoc/online-upgrade/iap/126b0fd3f48eb7e4c2a91.md","filePath":"sdoc/70-在线升级/01-IAP/LV060-IAP升级完整流程.md","lastUpdated":1792231946000}'),c={name:"sdoc/online-upgrade/iap/126b0fd3f48eb7e4c2a91.md"};function l(i,t,s,n,h,_){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="lv060-iap升级完整流程" tabindex="-1">LV060-IAP升级完整流程 <a class="header-anchor" href="#lv060-iap升级完整流程" aria-label="Permalink to &quot;LV060-IAP升级完整流程&quot;">​</a></h1><h2 id="一、-为什么还要单独写一篇" tabindex="-1">一、 为什么还要单独写一篇 <a class="header-anchor" href="#一、-为什么还要单独写一篇" aria-label="Permalink to &quot;一、 为什么还要单独写一篇&quot;">​</a></h2><p>前面几篇把零件都拆过了：收帧状态机在 LV045，<code>go</code> 命令与跳转在 LV050，两种镜像的工程配置在 LV030 / LV035。但把 <code>app.img</code> 从串口发进去、到 APP 跑起来，这条链路横跨三个执行位置——<strong>USART1 中断</strong>、<strong>主循环</strong>、<strong>跳转时的硬件状态切换</strong>，任何一篇单独看都只剩半条链路。</p><p>常见的三类疑问恰好都落在接缝上：</p><ul><li>头收完之后，<strong>什么时候算这一帧收完</strong>？</li><li>校验到底校的是 <strong>Flash 里的镜像</strong>，还是 <strong>SRAM 里的镜像</strong>？</li><li>同样是 <code>go</code>，为什么 Flash 目标直接跳，SRAM 目标要<strong>先搬一次</strong>？</li></ul><p>本篇只负责把链路串直，细节仍以各篇为准。</p><h2 id="二、-端到端链路" tabindex="-1">二、 端到端链路 <a class="header-anchor" href="#二、-端到端链路" aria-label="Permalink to &quot;二、 端到端链路&quot;">​</a></h2><p>以 PC 通过串口发送一份 <code>app.img</code> 为例，一次升级的全部动作如下：</p><p><img src="'+r+'" alt="IAP 升级的完整流程"></p><p>这条链路不是一条直线，图上能看到三件事：</p><ul><li><strong>一处上下文分界</strong>：<code>iap_rx_poll()</code> 返回 <code>IAP_EVT_FRAME_OK</code> 的那一刻。之前一切都在中断里，只做&quot;把字节装进帧&quot;，不校验、不落盘、不打印；之后一切都在主循环里，依次是校验、落盘、回执、等命令、跳转；</li><li><strong>一个失败回路</strong>：尾部不符、CRC32 不符、或者 3 s 超时，都走同一条退路——丢弃整帧、回到 <code>SCAN</code> 重新对齐，命令行照常可用，不必重启；</li><li><strong>一个决定去处的判断</strong>：帧头声明的目标地址只有两个合法值，<code>0x08020000</code> 走左路（就地执行），<code>0x20007000</code> 走右路（先落暂存区，<code>go sram</code> 时才搬进内部 RAM）。两路最后汇到同一个跳转动作。</li></ul><h2 id="三、-阶段与代码的对照" tabindex="-1">三、 阶段与代码的对照 <a class="header-anchor" href="#三、-阶段与代码的对照" aria-label="Permalink to &quot;三、 阶段与代码的对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>执行者</th><th>对应代码</th><th>结束条件</th></tr></thead><tbody><tr><td>等命令</td><td>主循环</td><td><code>iap_service_task()</code></td><td>收到字节流</td></tr><tr><td>对齐帧头</td><td>中断</td><td><code>iap_rx_byte()</code> → <code>IAP_ST_SCAN</code></td><td>8 字节滑窗命中 <code>IAPBIN02</code></td></tr><tr><td>读头部</td><td>中断</td><td><code>IAP_ST_HEADER</code></td><td>再收 12 字节，得到 N / CRC32 / 目标地址</td></tr><tr><td>收载荷</td><td>中断</td><td><code>IAP_ST_PAYLOAD</code></td><td>收满 N 字节，逐字节写进外部 SRAM</td></tr><tr><td>比对尾部</td><td>中断</td><td><code>IAP_ST_TRAILER</code></td><td>8 字节与 <code>IAPEOF02</code> 逐字节相等</td></tr><tr><td>帧级校验</td><td>主循环</td><td><code>iap_rx_poll()</code> → <code>IAP_ST_VERIFY</code></td><td>载荷 CRC32 与头部声明值相等，上报 <code>FRAME_OK</code></td></tr><tr><td>落盘</td><td>主循环</td><td><code>iap_install_image()</code></td><td>擦除 + 编程 + 回读 CRC 全部通过</td></tr><tr><td>回执</td><td>主循环</td><td><code>svc_on_frame_ok()</code></td><td>打印 <code>send &#39;go flash&#39;</code> 或 <code>send &#39;go sram&#39;</code>，<strong>不自动跳转</strong></td></tr><tr><td>跳转</td><td>主循环</td><td><code>cmd_go()</code> → <code>iap_load_app()</code></td><td>向量表合法则交出控制权，不返回</td></tr></tbody></table><h2 id="四、-三个接缝上的疑问" tabindex="-1">四、 三个接缝上的疑问 <a class="header-anchor" href="#四、-三个接缝上的疑问" aria-label="Permalink to &quot;四、 三个接缝上的疑问&quot;">​</a></h2><h3 id="_1-收完-是双条件-不是收够字节" tabindex="-1">1. &quot;收完&quot;是双条件，不是收够字节 <a class="header-anchor" href="#_1-收完-是双条件-不是收够字节" aria-label="Permalink to &quot;1. &quot;收完&quot;是双条件，不是收够字节&quot;">​</a></h3><p>只按长度判断是不够的：长度字段本身也可能被噪声改写。所以一帧收完要求两件事同时成立：</p><ul><li><code>IAP_ST_PAYLOAD</code> 收满头部声明的 N 字节；</li><li>紧接着的 8 字节与 <code>IAPEOF02</code> <strong>逐字节相等</strong>。</li></ul><p>尾部不一致不会去&quot;猜&quot;哪里少了字节，而是直接丢掉整帧、回到 <code>SCAN</code>。另外收帧中途字节间隔超过 <code>IAP_RX_TIMEOUT_MS</code>（3 s）也会判超时复位，避免主机中途取消后设备卡在半帧上。</p><h3 id="_2-crc32-校的是-sram-里的载荷-不是-flash" tabindex="-1">2. CRC32 校的是 SRAM 里的载荷，不是 Flash <a class="header-anchor" href="#_2-crc32-校的是-sram-里的载荷-不是-flash" aria-label="Permalink to &quot;2. CRC32 校的是 SRAM 里的载荷，不是 Flash&quot;">​</a></h3><p>按发生顺序，一共三层校验，对象各不相同：</p><table tabindex="0"><thead><tr><th>层</th><th>校验对象</th><th>位置</th><th>失败结果</th></tr></thead><tbody><tr><td>帧级 CRC32</td><td>外部 SRAM 载荷缓冲里刚收完的 N 字节</td><td><code>iap_rx_poll()</code></td><td><code>IAP_ERR_CRC</code>，整帧丢弃，不碰 Flash</td></tr><tr><td>落盘回读</td><td>Flash 里刚写进去的内容</td><td><code>iap_write_appbin()</code> / <code>iap_write_sram()</code></td><td><code>IAP_WR_ERR_VERIFY</code>，留在 Bootloader</td></tr><tr><td>向量表检查</td><td>目标地址处的前 8 字节</td><td><code>iap_app_is_valid()</code></td><td><code>iap_load_app()</code> 返回 -1，不跳转</td></tr></tbody></table><p>也就是说：<strong>协议层的完整性由帧级 CRC 保证，介质层的正确性由回读保证</strong>。前者防传输错误，后者防擦写错误，两者不能互相替代。</p><h3 id="_3-go-的分叉只在-要不要搬运" tabindex="-1">3. <code>go</code> 的分叉只在&quot;要不要搬运&quot; <a class="header-anchor" href="#_3-go-的分叉只在-要不要搬运" aria-label="Permalink to &quot;3. `go` 的分叉只在&quot;要不要搬运&quot;&quot;">​</a></h3><p><code>go</code> 是普通文本命令，走命令表，与帧协议没有关系；它只决定&quot;从哪儿开始执行&quot;：</p><table tabindex="0"><thead><tr><th>命令</th><th>目标基址</th><th>动作</th></tr></thead><tbody><tr><td><code>go flash</code></td><td><code>0x08020000</code></td><td>向量表检查通过后直接跳转，落盘位置就是运行位置</td></tr><tr><td><code>go sram</code></td><td><code>0x20007000</code></td><td>先 <code>iap_load_sram_app()</code> 从暂存区 <code>0x08040000</code> 拷 24 KB 进内部 SRAM，回读 CRC 通过再跳</td></tr><tr><td><code>go</code>（不带参数）</td><td>最近一次装好的镜像</td><td>同上，按该镜像的类型选路径</td></tr></tbody></table><p>SRAM 目标多一次搬运，是因为帧头声明的 <code>0x20007000</code> 是<strong>运行位置</strong>，而 Flash 里只有<strong>暂存位置</strong>。这样设计的好处是掉电后镜像还在暂存区，重新上电直接 <code>go sram</code> 就能跑，不必重发帧。</p><h2 id="五、-失败一律回到命令行" tabindex="-1">五、 失败一律回到命令行 <a class="header-anchor" href="#五、-失败一律回到命令行" aria-label="Permalink to &quot;五、 失败一律回到命令行&quot;">​</a></h2><p>链路上任何一步失败——超时、尾部不符、CRC 不符、擦写失败、向量表不合法——都不会复位，也不会锁死：状态机回到 <code>SCAN</code>，主循环回到命令行，<strong>直接重发即可</strong>。这一点是设计目标，不是巧合：升级本来就要面对不可靠的串口和随时可能断电的现场。</p><h2 id="六、-与其它各篇的分工" tabindex="-1">六、 与其它各篇的分工 <a class="header-anchor" href="#六、-与其它各篇的分工" aria-label="Permalink to &quot;六、 与其它各篇的分工&quot;">​</a></h2><ul><li>收帧状态机的逐状态细节：LV045《IAP 串口接收与帧处理》</li><li>帧格式与 <code>app.img</code> 的打包：LV040《image 镜像文件打包原理与生成》</li><li>Flash 分区与擦写实现：LV050《IAP 跳转与向量表原理》</li><li>两种镜像的工程配置：LV030《FLASH APP 设计》、LV035《SRAM APP 设计》</li><li>升级过程中的喂狗：LV055《看门狗问题与解决方案》</li></ul>',30)])])}const g=d(c,[["render",l]]);export{u as __pageData,g as default};
